func (c *Config) validate() error {
	if c.Key != "_id" {
		return errors.Errorf("sharding only supported on key '_id' for now, "+
			"got: %s", c.Key)
	}
	if c.Strategy != "hash" { ... }
	if c.Function != "murmur3" { ... }
	return nil
}
